{% assign error_code = 'AUTHENTICATION_FAILED' %}
{% assign error_message = 'Unable to authenticate with the product service.' %}
{% assign token = '' %}
{% assign products_ready = false %}
{% call {"requestId": "jwt-liquid-authenticate"} as authentication %}
{% assign has_status = authentication | has_key: 'status' %}
{% assign has_data = authentication | has_key: 'data' %}
{% if has_status and has_data %}
  {% if authentication.status == 200 %}
    {% assign has_token = authentication.data | has_key: 'accessToken' %}
    {% if has_token %}
      {% assign token_is_string = authentication.data.accessToken | is_type: 'string' %}
      {% if token_is_string %}
        {% assign token = authentication.data.accessToken %}
      {% endif %}
    {% endif %}
  {% endif %}
{% endif %}
{% if token != '' %}
  {% assign error_code = 'PRODUCTS_UNAVAILABLE' %}
  {% assign error_message = 'Unable to load products. Please try again.' %}
  {% assign authorization = 'Bearer ' | append: token %}
  {% call {
    "requestId": "jwt-liquid-products",
    "headersEmbedded": {"Authorization": {{ authorization | json }}}
  } as product_response %}
  {% assign has_status = product_response | has_key: 'status' %}
  {% assign has_data = product_response | has_key: 'data' %}
  {% if has_status and has_data %}
    {% if product_response.status == 200 %}
      {% assign has_products = product_response.data | has_key: 'products' %}
      {% if has_products %}
        {% assign products_ready = product_response.data.products | is_type: 'array' %}
      {% endif %}
    {% endif %}
  {% endif %}
  {% if products_ready %}
    {% capture product_json %}
    [
      {% for product in product_response.data.products limit: 3 %}
        {% assign has_id = product | has_key: 'id' %}
        {% assign has_title = product | has_key: 'title' %}
        {% assign has_price = product | has_key: 'price' %}
        {% if has_id and has_title and has_price %}
          {% assign id_valid = product.id | is_type: 'integer' %}
          {% assign title_valid = product.title | is_type: 'string' %}
          {% assign price_valid = product.price | is_type: 'number' %}
          {% if id_valid and title_valid and price_valid %}
            {% unless forloop.first %},{% endunless %}
            {"id": {{ product.id | json }}, "title": {{ product.title | json }}, "price": {{ product.price | json }}}
          {% else %}
            {% assign products_ready = false %}
          {% endif %}
        {% else %}
          {% assign products_ready = false %}
        {% endif %}
      {% endfor %}
    ]
    {% endcapture %}
  {% endif %}
{% endif %}
{% if products_ready %}
{"ok": true, "products": {{ product_json }}}
{% else %}
{"ok": false, "code": {{ error_code | json }}, "message": {{ error_message | json }}}
{% endif %}
